def forward(self, x):
    mu, logvar = self.encode(x)
    z = self.reparameterize(mu, logvar)
    x_recon = self.decode(z)

    return {
        'reconstruction': x_recon,
        'mu': mu,
        'logvar': logvar,
        'latent': z
    }

def forward(self, x):
    # Simplified quantization for testing
    batch_size, seq_len, dim = x.shape
    indices = torch.randint(0, 64, (batch_size, seq_len, len(self.quantizers)))
    quantized = x  # Pass through for now
    return {
        'quantized': quantized,
        'indices': indices,
        'commitment_loss': torch.tensor(0.1)
    }

def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, List[torch.Tensor]]:
    """Forward pass returning final output and intermediate features."""
    features = []

    for layer in self.layers:
        x = layer(x)
        # Save features from conv layers (skip activations)
        if isinstance(layer, nn.Conv1d):
            features.append(x)

    # Final prediction
    output = self.final(x)

    return output,
